"""Editorial research home. Data and stages remain separate from presentation."""
from pathlib import Path
def render(data,card,categories,shell,esc):
 root=Path(__file__).resolve().parents[1]
 title_svg=(root/'assets/preview-title.svg').read_text()
 robot_svg='<figure class="robot-vignette">'+(root/'assets/hero-robot.svg').read_text()+'<figcaption class="robot-vignette__caption"><span>概念示意，非实验演示</span></figcaption></figure>'
 papers=data['papers'];total=len(papers);counts={k:sum(p['category']==k for p in papers) for k in categories}
 tabs=f'<button class="topic-filter active" type="button" data-topic="all" aria-pressed="true"><span>全部</span><b>{total}</b></button>'
 labels={'navigation':'具身导航','wbc':'全身控制','vla':'视觉语言动作','foundations':'基础与评测'}
 tabs+=''.join(f'<button class="topic-filter" type="button" data-topic="{key}" aria-pressed="false"><span>{labels[key]}</span><b>{counts[key]}</b></button>' for key in categories)
 years=sorted({p['publication_year'] for p in papers if p.get('publication_year')},reverse=True)
 options=''.join(f'<option value="{y}">{y}</option>' for y in years)
 ordered=sorted(papers,key=lambda p:(not p['citation_verified'],-(p.get('bibliographic_year') or 0),p['title'].casefold()))
 body=f'''<main id="main" class="atlas-experience"><section class="experience-hero" aria-labelledby="hero-title"><div class="experience-hero-copy"><h1 id="hero-title" class="experience-title"><span class="sr-only">RoboPaperAtlas</span>{title_svg}</h1><p>探索机器人研究的论文、方法与原始证据。<br>从一篇论文开始，把发现放回可追溯的研究路径。</p><div class="experience-hero-actions"><a class="experience-primary vector-button" href="#catalog">浏览论文 <span aria-hidden="true">↗</span><i class="corner c1" aria-hidden="true"></i><i class="corner c2" aria-hidden="true"></i><i class="corner c3" aria-hidden="true"></i><i class="corner c4" aria-hidden="true"></i></a><a class="experience-secondary" href="frontier/index.html">阅读本期摘要 ↗</a></div></div><div class="experience-hero-scene">{robot_svg}</div></section><section class="experience-routes" aria-label="探索入口"><a class="experience-route route-catalog" href="#catalog"><span aria-hidden="true">⌕</span><div><h2>论文目录</h2><p>{total} 条书目，从标题、作者或研究方向开始。</p></div></a><a class="experience-route route-frontier" href="frontier/index.html#daily-brief"><span aria-hidden="true">↗</span><div><h2>前沿动态</h2><p>先看摘要速览，再展开自动匹配的候选线索。</p></div></a><a class="experience-route route-reading" href="about/index.html"><span aria-hidden="true">≡</span><div><h2>阅读档案</h2><p>了解分阶段阅读。实际报告尚未导入。</p></div></a></section><section class="catalog-section" id="catalog" aria-labelledby="catalog-title"><div class="section-heading"><div><h2 id="catalog-title">下一篇，<span>从这里开始。</span></h2><p>{total} 条论文书目 · 来源核验与阅读完成分开记录</p></div><a class="text-link" href="about/index.html#standards">收录与核验说明 ↗</a></div><div class="catalog-toolbar"><div class="topic-filters" role="group" aria-label="研究方向">{tabs}<span class="topic-indicator" aria-hidden="true"></span></div><button type="button" class="catalog-search-trigger" data-search-trigger><span id="catalog-search-label">搜索标题、作者或关键词</span><kbd>/</kbd></button></div><div class="catalog-main"><input id="search" type="hidden" value=""><div class="results-bar"><p id="result-count" role="status" aria-live="polite">共 {total} 篇论文</p><div class="results-actions"><details class="filter-disclosure"><summary>筛选 <span aria-hidden="true">＋</span></summary><div class="filter-panel"><label>出版年份<select id="year-filter"><option value="all">全部年份</option>{options}<option value="unknown">未知 / 尚无正式出版年</option></select></label><label>核验状态<select id="status-filter"><option value="all">全部状态</option><option value="verified">来源已核验</option><option value="pending">书目待核验</option></select></label><p>仅按已核验的正式出版年筛选；预印本年与原始记录年分开保存。</p></div></details><label class="sort-label"><span class="sr-only">排序</span><select id="sort"><option value="curated">来源核验优先</option><option value="newest">记录年份降序</option><option value="title">标题 A → Z</option></select></label><div class="view-switch" role="group" aria-label="目录显示方式"><button type="button" data-view="list" aria-pressed="false" aria-label="列表视图">☷</button><button type="button" data-view="cards" aria-pressed="true" aria-label="卡片视图">▦</button></div></div></div><div class="active-filters" id="active-filters" aria-label="当前筛选条件" hidden></div><div class="paper-grid" id="paper-grid">{''.join(card(p) for p in ordered)}</div><div class="empty-state" id="empty-state" hidden><h3>暂时没有匹配的论文</h3><p>换一个关键词，或放宽筛选条件。</p><button class="secondary-button" id="reset-filters" type="button">重置筛选</button></div><button class="load-more" id="load-more" type="button" hidden>显示更多论文 ↓</button><noscript><p class="noscript-note">当前已显示全部论文。搜索、筛选和快捷预览需要 JavaScript；点击题名仍可打开完整详情页。</p></noscript></div></section><section class="reading-roadmap"><div><h2>每一次阅读，<br>都留下可追溯的路径。</h2><p>实际报告导入后，按阶段与版本查阅。<br>来源核验、阅读完成与独立复现，始终分开记录。</p></div><div class="roadmap-stages"><div><span>01</span><h3>初读</h3><p>建立研究问题、核心贡献与证据入口。</p></div><div><span>02</span><h3>写作精读</h3><p>梳理论证结构、研究缺口与表达。</p></div><div><span>03</span><h3>方法精读</h3><p>结合公式、框架与公开代码理解方法。</p></div></div></section></main>'''
 return shell('RoboPaperAtlas',body)
